<?php
require 'config.php'; require_admin(); $page_title='Pengguna'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim($_POST['username']??'');$full=trim($_POST['full_name']??'');$password=$_POST['password']??'';$role=$_POST['role']??'staff';if($username===''||$full===''||strlen($password)<6||!in_array($role,['admin','staff'],true))$error='Lengkapi data. Password minimal 6 karakter.';else{try{$s=$pdo->prepare("INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,?)");$s->execute([$username,password_hash($password,PASSWORD_DEFAULT),$full,$role]);flash('Pengguna berhasil dibuat.');header('Location: users.php');exit;}catch(PDOException $e){$error='Username sudah digunakan.';}}}
$rows=$pdo->query("SELECT id,username,full_name,role,created_at FROM users ORDER BY id")->fetchAll();require 'partials/header.php';?>
<div class="page-head"><div><h1>Pengguna ♡</h1><div class="sub">Hanya admin yang dapat mengelola akun.</div></div></div>
<?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?>
<div class="card"><h2>Tambah Pengguna</h2><form method="post" class="form-grid"><div><label>Nama lengkap</label><input name="full_name" required></div><div><label>Username</label><input name="username" required></div><div><label>Password (min. 6 karakter)</label><input type="password" name="password" minlength="6" required></div><div><label>Role</label><select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></div><div style="align-self:end"><button class="btn">＋ Buat Akun</button></div></form></div>
<div class="card table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Dibuat</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><span class="badge"><?=e($r['role'])?></span></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php require 'partials/footer.php';?>
